-- Premium handles: generic words that are sold separately (one-time fee) and assigned by admin.
-- Run once on existing installs:  mysql -u kuantan1_wsap -p kuantan1_wsap < db/upgrade_007_premium_slugs.sql
CREATE TABLE IF NOT EXISTS premium_slugs (
  slug             VARCHAR(30)  NOT NULL PRIMARY KEY,
  price_myr        INT UNSIGNED NOT NULL DEFAULT 299,
  assigned_user_id INT UNSIGNED NULL,
  note             VARCHAR(120) NOT NULL DEFAULT '',
  created_at       DATETIME     NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

